<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue";
import { Activity, ArrowRight, Coins, Gauge, Plus, RefreshCw, ShoppingCart } from "lucide-vue-next";

import ModalPanel from "../components/ModalPanel.vue";
import PageHeader from "../components/PageHeader.vue";
import StatusBadge from "../components/StatusBadge.vue";
import { api, type Asset, type MetricDefinition, type MetricSample, type Provider, type ServiceInstance, type ServiceProduct } from "../lib/api";

type ModalKind = "provider" | "product" | "instance" | "metric" | null;
const loading = ref(true); const saving = ref(false); const error = ref(""); const modal = ref<ModalKind>(null); const metricTarget = ref("");
const providers = ref<Provider[]>([]); const products = ref<ServiceProduct[]>([]); const instances = ref<ServiceInstance[]>([]); const assets = ref<Asset[]>([]); const definitions = ref<MetricDefinition[]>([]); const samples = ref<Record<string, MetricSample[]>>({});
const providerForm = reactive({ code: "", name: "", website: "" });
const productForm = reactive({ provider_id: "", code: "", name: "", service_category: "large_model_api", billing_mode: "prepaid_balance" });
const instanceForm = reactive({ asset_id: "", service_product_id: "", purchase_platform_id: "", subscription_name: "", currency: "CNY", starts_at: "", expires_at: "" });
const metricForm = reactive({ metric_definition_id: "", value: 0, currency: "CNY", source_type: "manual" });
const productName = computed(() => Object.fromEntries(products.value.map((item) => [item.id, item.name])));
const assetName = computed(() => Object.fromEntries(assets.value.map((item) => [item.id, item.name])));
const definitionName = computed(() => Object.fromEntries(definitions.value.map((item) => [item.id, item.display_name])));
const latestMetricCount = computed(() => Object.values(samples.value).reduce((sum, rows) => sum + rows.length, 0));

async function load() { loading.value = true; try { const [providerRows, productRows, instanceRows, assetRows, definitionRows] = await Promise.all([api.providers(), api.serviceProducts(), api.serviceInstances(), api.assets(), api.metricDefinitions()]); providers.value = providerRows; products.value = productRows; instances.value = instanceRows; assets.value = assetRows.data; definitions.value = definitionRows; productForm.provider_id ||= providers.value[0]?.id ?? ""; instanceForm.service_product_id ||= products.value[0]?.id ?? ""; metricForm.metric_definition_id ||= definitions.value[0]?.id ?? ""; samples.value = Object.fromEntries(await Promise.all(instances.value.map(async (item) => [item.id, await api.metrics(item.id)] as const))); } catch (reason) { error.value = reason instanceof Error ? reason.message : "加载失败"; } finally { loading.value = false; } }
function openMetric(id: string) { metricTarget.value = id; modal.value = "metric"; }
async function save() { saving.value = true; error.value = ""; try { if (modal.value === "provider") await api.createProvider({ ...providerForm, website: providerForm.website || null }); if (modal.value === "product") await api.createServiceProduct(productForm); if (modal.value === "instance") await api.createServiceInstance({ ...instanceForm, purchase_platform_id: instanceForm.purchase_platform_id || null, starts_at: instanceForm.starts_at || null, expires_at: instanceForm.expires_at || null }); if (modal.value === "metric") await api.createMetric(metricTarget.value, metricForm); modal.value = null; await load(); } catch (reason) { error.value = reason instanceof Error ? reason.message : "保存失败"; } finally { saving.value = false; } }
onMounted(load);
</script>

<template>
  <div class="page-stack">
    <PageHeader title="服务与用量" description="先进入平台详情，再按该平台公开 API 实际支持的范围管理余额与额度。"><RouterLink to="/services/alerts" class="secondary-button">额度告警与通知</RouterLink><button class="secondary-button" @click="modal = 'provider'"><Plus :size="16" />供应商</button><button class="secondary-button" @click="modal = 'product'"><Plus :size="16" />服务产品</button><button class="primary-button" @click="modal = 'instance'"><Plus :size="17" />服务实例</button></PageHeader>
    <div v-if="error" class="message-panel error-message">{{ error }}</div>
    <section class="content-panel platform-directory"><div class="panel-heading"><div><h2>已接入平台</h2><p>每个平台按照官方可调用的接口单独实现，不将账户余额误当成 API Key 用量。</p></div></div><div class="platform-entry-grid"><RouterLink to="/services/deepseek" class="platform-entry"><div><strong>DeepSeek</strong><span>开放平台账号当前余额</span><small>不支持通过公开 API 查询各 Key 历史用量</small></div><ArrowRight :size="20" /></RouterLink><RouterLink to="/services/minimax" class="platform-entry"><div><strong>MiniMax</strong><span>Token Plan 套餐、额度与积分状态</span><small>普通按量 API Key 无公开余额/用量查询接口</small></div><ArrowRight :size="20" /></RouterLink><RouterLink to="/services/aliyun" class="platform-entry"><div><strong>阿里云</strong><span>账户可用额度、现金余额与信控余额</span><small>使用具有 BSS 只读权限的 RAM AccessKey 查询账户级余额</small></div><ArrowRight :size="20" /></RouterLink></div></section>
    <section class="metric-grid"><article class="metric-card"><span class="metric-icon"><ShoppingCart :size="20" /></span><span>产品目录</span><strong>{{ products.length }}</strong><small>API、SaaS和按量产品</small></article><article class="metric-card"><span class="metric-icon"><Coins :size="20" /></span><span>服务实例</span><strong>{{ instances.length }}</strong><small>公司实际购买或使用</small></article><article class="metric-card"><span class="metric-icon"><Activity :size="20" /></span><span>指标记录</span><strong>{{ latestMetricCount }}</strong><small>人工和自动来源均保留</small></article><article class="metric-card"><span class="metric-icon"><Gauge :size="20" /></span><span>可用指标</span><strong>{{ definitions.length }}</strong><small>余额、额度、Token与费用</small></article></section>
    <section class="content-panel services-panel"><div class="panel-heading"><div><h2>服务实例与最新指标</h2><p>平台同步的账户级余额和套餐额度，可按需要关联到服务实例归集。</p></div><button class="icon-button" @click="load"><RefreshCw :size="17" /></button></div><div class="service-grid"><article v-for="item in instances" :key="item.id"><header><div><strong>{{ item.subscription_name || assetName[item.asset_id] || '未命名服务' }}</strong><span>{{ productName[item.service_product_id] ?? '未知产品' }}</span></div><StatusBadge tone="success">已登记</StatusBadge></header><div class="service-metrics"><div v-for="metric in (samples[item.id] ?? []).slice(0, 4)" :key="metric.id"><span>{{ definitionName[metric.metric_definition_id] }}</span><strong>{{ metric.value }} {{ metric.currency || '' }}</strong><small>{{ new Date(metric.collected_at).toLocaleString('zh-CN') }}</small></div><div v-if="!(samples[item.id] ?? []).length" class="mini-empty">尚未录入余额或用量</div></div><footer><span>到期：{{ item.expires_at || '未设置' }}</span><button class="secondary-button" @click="openMetric(item.id)"><Plus :size="15" />录入指标</button></footer></article><div v-if="!instances.length && !loading" class="large-empty-panel"><Activity :size="28" /><strong>尚未建立服务实例</strong><p>先在资产中心登记 API 或 SaaS 资产，再关联服务产品和购买渠道。</p><button class="primary-button" @click="modal = 'instance'"><Plus :size="16" />建立服务实例</button></div></div></section>
    <ModalPanel v-if="modal" :title="modal === 'provider' ? '新增供应商' : modal === 'product' ? '新增服务产品' : modal === 'instance' ? '建立服务实例' : '录入余额或用量'" @close="modal = null"><form class="form-grid one-column" @submit.prevent="save"><template v-if="modal === 'provider'"><label><span>供应商编码 *</span><input v-model="providerForm.code" required placeholder="例如 DEEPSEEK" /></label><label><span>供应商名称 *</span><input v-model="providerForm.name" required /></label><label><span>官网</span><input v-model="providerForm.website" /></label></template><template v-if="modal === 'product'"><label><span>产品提供方 *</span><select v-model="productForm.provider_id" required><option v-for="item in providers" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label><span>产品编码 *</span><input v-model="productForm.code" required /></label><label><span>产品名称 *</span><input v-model="productForm.name" required /></label><label><span>服务类别</span><select v-model="productForm.service_category"><option value="large_model_api">大模型API</option><option value="saas">SaaS</option><option value="cloud">云服务</option><option value="other">其他</option></select></label><label><span>计费模式</span><select v-model="productForm.billing_mode"><option value="prepaid_balance">预付余额</option><option value="usage">按量</option><option value="monthly">包月</option></select></label></template><template v-if="modal === 'instance'"><div class="form-hint">服务实例必须对应一项公司资产。</div><label><span>对应资产 *</span><select v-model="instanceForm.asset_id" required><option value="" disabled>选择资产</option><option v-for="item in assets.filter((row) => !instances.some((instance) => instance.asset_id === row.id))" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label><span>服务产品 *</span><select v-model="instanceForm.service_product_id" required><option v-for="item in products" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label><span>实例/套餐名称</span><input v-model="instanceForm.subscription_name" /></label><label><span>币种</span><select v-model="instanceForm.currency"><option>CNY</option><option>USD</option></select></label><label><span>开始日期</span><input v-model="instanceForm.starts_at" type="date" /></label><label><span>到期日期</span><input v-model="instanceForm.expires_at" type="date" /></label></template><template v-if="modal === 'metric'"><label><span>指标 *</span><select v-model="metricForm.metric_definition_id" required><option v-for="item in definitions" :key="item.id" :value="item.id">{{ item.display_name }}（{{ item.unit }}）</option></select></label><label><span>数值 *</span><input v-model.number="metricForm.value" type="number" step="0.0001" required /></label><label><span>币种（金额指标）</span><select v-model="metricForm.currency"><option>CNY</option><option>USD</option></select></label></template><div class="form-actions"><button type="button" class="secondary-button" @click="modal = null">取消</button><button class="primary-button" :disabled="saving">{{ saving ? '保存中…' : '保存' }}</button></div></form></ModalPanel>
  </div>
</template>
